{
  "lesson_summary": "Today's lesson plans to teach children how to count backwards from 9 to 0, understanding that each step involves saying one less. The lesson uses the example of Bunty on a hopscotch to demonstrate counting back from 9, and then applies this skill to word problems involving pigeons flying away from a roof.",
  "lesson_summary_short": "Today's lesson plans to teach counting backwards from 9 to 0, using the hopscotch example.",
  "checks_summary": "This quiz checks whether the class can count backwards from 9 to 0 and apply this skill to find remaining quantities.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "Which number comes after 9 when counting backwards?",
      "options": [
        "8",
        "10",
        "9"
      ],
      "correct_index": 0,
      "explanation": "When counting backwards from 9, the next number is one less than 9, which is 8.",
      "selected_because": "The lesson starts by counting backwards from 9.",
      "distractor_misconceptions": {
        "1": "Confuses counting backwards with counting forwards.",
        "2": "Repeats the starting number instead of moving to the next."
      },
      "option_feedback": {
        "correct": "That's right! When you count backwards from 9, the next number is 8.",
        "wrong": {
          "1": "This is counting forwards. When counting backwards, you say one less than the number before. Try again!",
          "2": "When counting backwards, you need to say a different number. Think about what is one less than 9."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Say the start aloud: 9 Backwards means one step down. One less than 9 is 8 — write 8",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Bunty is on 7 in hopscotch. What is one less?",
      "options": [
        "6",
        "8",
        "7"
      ],
      "correct_index": 0,
      "explanation": "To find one less than 7, you subtract 1 from 7, which gives you 6.",
      "selected_because": "Applies the 'one less' concept to a number from the hopscotch example.",
      "distractor_misconceptions": {
        "1": "Confuses 'one less' with 'one more'.",
        "2": "Repeats the number instead of finding 'one less'."
      },
      "option_feedback": {
        "correct": "Excellent! One less than 7 is 6. You are counting backwards correctly.",
        "wrong": {
          "1": "This is one more than 7. When counting backwards, you need to find one less. Try again!",
          "2": "Remember, 'one less' means you take away one. What happens when you take one away from 7?"
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "One less than 9 is 8 — write 8 Check: 8 is one less than 9",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "What happens to the number when you count backwards?",
      "options": [
        "It becomes one less.",
        "It becomes one more.",
        "It stays the same."
      ],
      "correct_index": 0,
      "explanation": "When counting backwards, each number in the sequence is always one less than the previous number.",
      "selected_because": "Checks the core concept of counting backwards.",
      "distractor_misconceptions": {
        "1": "Confuses the direction of counting.",
        "2": "Believes the number does not change."
      },
      "option_feedback": {
        "correct": "That's right! When counting backwards, every next number is one less than the one before it.",
        "wrong": {
          "1": "This describes counting forwards. When counting backwards, the number gets smaller, not bigger.",
          "2": "If the number stayed the same, you wouldn't be counting! When counting backwards, the number changes to one less."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "When we count backwards, every next number is one less: 9, 8, 7, 6, 5, 4, 3, 2, 1, 0.",
      "teaching_error": null
    },
    {
      "slo_id": "S3",
      "level": "apply",
      "question": "Bunty saw 9 birds. 3 flew away. How many birds are left?",
      "options": [
        "6",
        "12",
        "9"
      ],
      "correct_index": 0,
      "explanation": "Starting with 9 birds, if 3 fly away, you count backwards 3 times: 9, 8, 7, 6. So, 6 birds are left.",
      "selected_because": "Applies counting backwards to a word problem from the lesson.",
      "distractor_misconceptions": {
        "1": "Adds the numbers instead of subtracting.",
        "2": "Does not perform any operation, just repeats the initial number."
      },
      "option_feedback": {
        "correct": "Great job! You counted backwards 3 times from 9 (9, 8, 7, 6) to find that 6 birds are left.",
        "wrong": {
          "1": "This is what happens if you add the birds. When some fly away, you need to count backwards to find how many are left.",
          "2": "Remember, some birds flew away, so the number of birds left will be less than 9. Count backwards to find the answer."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Bunty saw 9 pigeons on the roof. Three flew away. Count backwards: how many are left?",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Which sequence shows counting backwards?",
      "options": [
        "9, 8, 7",
        "7, 8, 9",
        "9, 9, 8"
      ],
      "correct_index": 0,
      "explanation": "Counting backwards means each number is one less than the previous one, as in 9, 8, 7.",
      "selected_because": "Identifies a correct sequence of counting backwards.",
      "distractor_misconceptions": {
        "1": "Confuses backwards counting with forwards counting.",
        "2": "Repeats a number in the sequence."
      },
      "option_feedback": {
        "correct": "Yes, 9, 8, 7 is a correct sequence for counting backwards! Each number is one less.",
        "wrong": {
          "1": "This sequence is counting forwards. When counting backwards, the numbers should get smaller.",
          "2": "In this sequence, a number is repeated. When counting backwards, each number should be different and one less than the previous."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "When we count backwards, every next number is one less: 9, 8, 7, 6, 5, 4, 3, 2, 1, 0.",
      "teaching_error": null
    },
    {
      "slo_id": "S3",
      "level": "apply",
      "question": "There are 6 birds. 4 more fly away. How many birds are left?",
      "options": [
        "2",
        "10",
        "6"
      ],
      "correct_index": 0,
      "explanation": "Starting with 6 birds, if 4 fly away, you count backwards 4 times: 6, 5, 4, 3, 2. So, 2 birds are left.",
      "selected_because": "Applies counting backwards to a second word problem from the lesson.",
      "distractor_misconceptions": {
        "1": "Adds the numbers instead of subtracting.",
        "2": "Does not perform any operation, just repeats the initial number."
      },
      "option_feedback": {
        "correct": "That's right! Counting backwards 4 times from 6 (6, 5, 4, 3, 2) leaves 2 birds.",
        "wrong": {
          "1": "This would be true if more birds came. When birds fly away, you need to count backwards.",
          "2": "Since 4 birds flew away, the number of birds left must be less than 6. Count backwards to find out how many."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Now 6 pigeons sit on the roof. Four more fly away. Count backwards: how many are left now?",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which number is missing: ___, 7, 6, 5?",
      "options": [
        "8",
        "9",
        "7"
      ],
      "correct_index": 0,
      "explanation": "In a backwards sequence, the number before 7 is one more than 7, which is 8.",
      "selected_because": "Completes a short backwards sequence, checking understanding of 'one less'.",
      "distractor_misconceptions": {
        "1": "Confuses the start of the sequence with the end.",
        "2": "Repeats a number already in the sequence."
      },
      "option_feedback": {
        "correct": "Correct! When counting backwards, 8 comes before 7.",
        "wrong": {
          "1": "The sequence is going backwards, so the number before 7 should be larger. Think about what comes before 7 when counting backwards.",
          "2": "The number 7 is already in the sequence. You need to find the number that comes before 7 when counting backwards."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Complete the backwards sequence: ___, 7, ___, 5, ___, 3, ___, 1, ___.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "What is the last number when counting backwards from 9 to 0?",
      "options": [
        "0",
        "1",
        "9"
      ],
      "correct_index": 0,
      "explanation": "The lesson specifically teaches counting backwards from 9 all the way to 0.",
      "selected_because": "Checks the end point of the backwards counting sequence taught.",
      "distractor_misconceptions": {
        "1": "Confuses the last number with the second to last.",
        "2": "Confuses the last number with the starting number."
      },
      "option_feedback": {
        "correct": "Yes, 0 is the last number when you count backwards from 9 to 0!",
        "wrong": {
          "1": "1 is close, but you can count one more step backwards from 1. What comes after 1 when counting backwards?",
          "2": "9 is where you start! When you count backwards, you keep going until you reach the very last number."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Count backwards from 9 to 0, saying one less at every step.",
      "teaching_error": null
    }
  ]
}
